const input = $input.first().json;
const html = input.data || input.body || input || '';
const htmlStr = typeof html === 'string' ? html : JSON.stringify(html);
const BASE_URL = 'https://dukuhtengah-bojong.desa.id/';

let userMessage = input.message || '';
if (!userMessage) {
  try {
    userMessage = $('Edit Fields').first().json.message || '';
  } catch (error) {
    userMessage = '';
  }
}

const normalizedMessage = userMessage.toLowerCase();
const FALLBACK_NOT_FOUND = 'INFORMASI TERKAIT TIDAK DITEMUKAN DI SUMBER RESMI.';

const structuredFacts = {
  village: 'Desa Dukuhtengah',
  district: 'Kecamatan Bojong',
  regency: 'Kabupaten Tegal',
  province: 'Jawa Tengah',
  officeAddress: 'Jl. Raya Dukuhtengah Kecamatan Bojong Kabupaten Tegal',
  postalCode: '52465',
  phone: '-',
  email: '-',
  serviceHours: 'Senin-Jumat, 08.00-15.00 WIB',
  servicePortal: 'https://pelayanandesadukuhtengah.my.id/',
  officialWebsite: BASE_URL,
  officials: [
    { name: 'WARIS', role: 'Kepala Desa' },
    { name: 'PIPIT SUPRIA', role: 'Sekretaris' },
    { name: 'RIZAL AFRIANTO', role: 'Bendahara' },
    { name: 'AKHMAD ASMAWI', role: 'Kaur Perencanaan' },
    { name: 'LUKMAN NUROPIK', role: 'Kasi Kesra' },
    { name: 'RINA SUPRIHATI', role: 'Kasi Pemerintahan' },
    { name: 'SULISTIYOWATI', role: 'Kasi Pelayanan' },
    { name: 'ANDRI AJAT SETIAWAN', role: 'Kaur TU' },
  ],
  services: [
    'KTP',
    'Kartu Keluarga',
    'Surat Keterangan Domisili',
    'Akta Kelahiran',
    'Surat Keterangan Tidak Mampu',
    'Surat Keterangan Usaha',
  ],
};

function decodeEntities(text) {
  return String(text || '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)))
    .replace(/&#([0-9]+);/g, (_, code) => String.fromCharCode(parseInt(code, 10)));
}

function normalizeSpaces(text) {
  return String(text || '').replace(/\s+/g, ' ').trim();
}

function cleanHtml(rawHtml) {
  return decodeEntities(rawHtml)
    .replace(/<head[\s\S]*?<\/head>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<canvas[\s\S]*?<\/canvas>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|section|article|aside|footer|header|nav|li|tr|td|h[1-6])>/gi, '\n')
    .replace(/<(?:\"[^\"]*\"|'[^']*'|[^'\">])*>/g, ' ')
    .replace(/\{\s*this\.loading[\s\S]*?x-init="onLoading\(\)"/gi, ' ')
    .replace(/document\.querySelector\([^)]*\)[^\s]*/gi, ' ')
    .replace(/[ \t\r\f\v]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function includesAny(text, terms) {
  return terms.some((term) => text.includes(term));
}

function tokenize(text) {
  const stopWords = new Set([
    'apa', 'itu', 'yang', 'dan', 'atau', 'di', 'ke', 'dari', 'dalam', 'untuk', 'dengan',
    'siapa', 'bagaimana', 'gimana', 'berapa', 'kapan', 'mana', 'adalah', 'saya', 'ingin',
    'mau', 'menanyakan', 'tentang', 'desa', 'dukuhtengah', 'kecamatan', 'bojong', 'kabupaten',
    'tegal', 'provinsi', 'jawa', 'tengah', 'resmi', 'website', 'info', 'informasi', 'ada',
    'tidak', 'kantor', 'lokasi', 'alamat',
  ]);

  return Array.from(new Set(
    String(text || '')
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, ' ')
      .split(/\s+/)
      .map((token) => token.trim())
      .filter((token) => token.length >= 3 && !stopWords.has(token))
  ));
}

function sectionBetween(text, startMarker, endMarkers) {
  const lowerText = text.toLowerCase();
  const start = lowerText.indexOf(startMarker.toLowerCase());
  if (start === -1) {
    return '';
  }

  const afterStart = start + startMarker.length;
  let end = text.length;
  for (const marker of endMarkers) {
    const markerIndex = lowerText.indexOf(marker.toLowerCase(), afterStart);
    if (markerIndex !== -1 && markerIndex < end) {
      end = markerIndex;
    }
  }

  return normalizeSpaces(startMarker + ' ' + text.slice(afterStart, end));
}

function structuredFactsText() {
  return [
    'DATA TERSTRUKTUR DESA',
    `Nama: ${structuredFacts.village}`,
    `Wilayah: ${structuredFacts.district}, ${structuredFacts.regency}, ${structuredFacts.province}`,
    `Alamat kantor: ${structuredFacts.officeAddress}`,
    `Kodepos: ${structuredFacts.postalCode}`,
    `Telepon: ${structuredFacts.phone}`,
    `Email: ${structuredFacts.email}`,
    `Jam layanan kantor: ${structuredFacts.serviceHours}`,
    `Portal layanan mandiri: ${structuredFacts.servicePortal}`,
    `Website resmi: ${structuredFacts.officialWebsite}`,
    `Layanan yang dikenal: ${structuredFacts.services.join(', ')}`,
  ].join('\n');
}

function extractDetailDesa(text) {
  const section = sectionBetween(text, 'Detail Desa', ['Statistik Pengunjung', 'APBDes', 'Hak cipta situs']);
  const address = /Alamat\s*:?\s*(.*?)(?=\s+Desa\s*:|\s+Kecamatan\s*:|\s+Kabupaten\s*:|\s+Kodepos\s*:|$)/i.exec(section)?.[1]?.trim();
  const postalCode = /Kodepos\s*:?\s*([0-9]+)/i.exec(section)?.[1]?.trim();
  const phoneRaw = /Telepon\s*:?\s*(.*?)(?=\s+Email\s*:|$)/i.exec(section)?.[1]?.trim();
  const phone = phoneRaw && !/^email\b/i.test(phoneRaw) ? phoneRaw : '';
  const email = /Email\s*:?\s*([^\s]+@[^\s]+)?/i.exec(section)?.[1]?.trim();

  return {
    text: [
      'DETAIL DESA',
      `Alamat: ${address || structuredFacts.officeAddress}`,
      `Desa: ${structuredFacts.village.replace(/^Desa\s+/i, '')}`,
      `Kecamatan: ${structuredFacts.district.replace(/^Kecamatan\s+/i, '')}`,
      `Kabupaten: ${structuredFacts.regency.replace(/^Kabupaten\s+/i, '')}`,
      `Kodepos: ${postalCode || structuredFacts.postalCode}`,
      `Telepon: ${phone || structuredFacts.phone}`,
      `Email: ${email || structuredFacts.email}`,
      `Jam layanan kantor: ${structuredFacts.serviceHours}`,
    ].join('\n'),
    found: section.length > 0,
  };
}

function formatOfficials(officials) {
  return [
    'PEMERINTAH DESA',
    ...officials.map((official) => `${official.role}: ${official.name}`),
  ].join('\n');
}

function extractPemerintahDesa(text) {
  const section = sectionBetween(text, 'Pemerintah Desa', ['Komentar', 'Media Sosial', 'Peta Wilayah Desa']);
  const fallbackOfficials = structuredFacts.officials;

  if (section) {
    const cleaned = section
      .replace(/\bImage:\s*/gi, '')
      .replace(/\bBelum Rekam Kehadiran\b/gi, '')
      .replace(/\s+/g, ' ')
      .trim();

    const parsedOfficials = fallbackOfficials
      .map((official) => ({
        name: official.name,
        role: official.role,
        found: cleaned.toLowerCase().includes(official.name.toLowerCase())
          && cleaned.toLowerCase().includes(official.role.toLowerCase()),
      }))
      .filter((official) => official.found)
      .map(({ name, role }) => ({ name, role }));

    return {
      text: formatOfficials(parsedOfficials.length > 0 ? parsedOfficials : fallbackOfficials),
      found: true,
    };
  }

  return {
    text: formatOfficials(fallbackOfficials),
    found: false,
  };
}

function extractAgenda(text) {
  const section = sectionBetween(text, 'Agenda', ['Sinergi Program', 'Galeri', 'Pemerintah Desa']);
  return {
    text: section || 'AGENDA\nBelum ada agenda yang terbaca dari website resmi.',
    found: section.length > 0,
  };
}

function absolutizeUrl(url) {
  const rawUrl = String(url || '').trim();

  if (!rawUrl || rawUrl.startsWith('#')) {
    return '';
  }

  if (/^(javascript:|mailto:|tel:)/i.test(rawUrl)) {
    return '';
  }

  if (/^https?:\/\//i.test(rawUrl)) {
    return rawUrl;
  }

  if (rawUrl.startsWith('//')) {
    return 'https:' + rawUrl;
  }

  const base = BASE_URL.replace(/\/+$/, '');

  if (rawUrl.startsWith('/')) {
    return base + rawUrl;
  }

  return base + '/' + rawUrl.replace(/^\.?\//, '');
}

function extractArticleCandidates(rawHtml) {
  const decoded = decodeEntities(rawHtml);
  const linkRegex = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  const candidates = [];
  let match;

  while ((match = linkRegex.exec(decoded)) !== null) {
    const url = absolutizeUrl(match[1]);
    if (!url) {
      continue;
    }
    const title = normalizeSpaces(match[2].replace(/<[^>]+>/g, ' '));
    if (!/\/artikel\/\d{4}\/\d{1,2}\/\d{1,2}\//i.test(url) || title.length < 4) {
      continue;
    }

    const after = decoded.slice(match.index + match[0].length, match.index + match[0].length + 900);
    const excerpt = normalizeSpaces(after.replace(/<[^>]+>/g, ' ')).slice(0, 500);
    const date = /(\d{1,2}\s+[A-Za-z]+\s+\d{4})/.exec(excerpt)?.[1] || '';
    candidates.push({ title, url, excerpt, date });
  }

  const unique = new Map();
  for (const candidate of candidates) {
    const key = candidate.url.replace(/\/0(\d)\//g, '/$1/');
    const current = unique.get(key);
    if (!current || candidate.excerpt.length > current.excerpt.length) {
      unique.set(key, candidate);
    }
  }

  return Array.from(unique.values()).slice(0, 10);
}

function scoreText(text, tokens) {
  const lower = String(text || '').toLowerCase();
  let score = 0;
  for (const token of tokens) {
    if (lower.includes(token)) {
      score += token.length >= 5 ? 3 : 1;
    }
  }
  for (let index = 0; index < tokens.length - 1; index += 1) {
    const phrase = tokens[index] + ' ' + tokens[index + 1];
    if (lower.includes(phrase)) {
      score += 4;
    }
  }
  return score;
}

async function getArticleDetail(article) {
  if (typeof fetch !== 'function') {
    return null;
  }

  try {
    const response = await fetch(article.url, {
      method: 'GET',
      headers: { 'User-Agent': 'n8n-desa-dukuhtengah-bot/1.0' },
    });
    if (!response.ok) {
      return null;
    }
    const detailHtml = await response.text();
    const detailText = cleanHtml(detailHtml);
    const detail = sectionBetween(detailText, article.title, ['Komentar', 'Media Sosial', 'Artikel Terkini', 'Kategori']);
    return normalizeSpaces(detail || detailText).slice(0, 2200);
  } catch (error) {
    return null;
  }
}

async function findArticleContext(rawHtml, message) {
  const tokens = tokenize(message);
  const candidates = extractArticleCandidates(rawHtml)
    .map((candidate) => ({
      ...candidate,
      score: scoreText(`${candidate.title} ${candidate.excerpt}`, tokens),
    }))
    .filter((candidate) => candidate.score > 0)
    .sort((a, b) => b.score - a.score || b.excerpt.length - a.excerpt.length)
    .slice(0, 3);

  if (candidates.length === 0) {
    return null;
  }

  const enriched = [];
  for (const article of candidates) {
    const detail = await getArticleDetail(article);
    enriched.push({ ...article, detail });
  }

  return {
    text: [
      'ARTIKEL TERKAIT',
      ...enriched.map((article) => [
        `Judul: ${article.title}`,
        article.date ? `Tanggal: ${article.date}` : '',
        article.detail ? `Isi halaman detail: ${article.detail}` : `Ringkasan dari homepage: ${article.excerpt}`,
        `Sumber detail: ${article.url}`,
      ].filter(Boolean).join('\n')),
    ].join('\n\n'),
    candidates: enriched,
    usedDetail: enriched.some((article) => Boolean(article.detail)),
  };
}

function splitIntoChunks(text) {
  const headingMarkers = [
    'SELAMAT DATANG',
    'Artikel Terkini',
    'Menu Kategori',
    'Statistik',
    'Arsip Artikel',
    'Agenda',
    'Sinergi Program',
    'Galeri',
    'Pemerintah Desa',
    'Komentar',
    'Media Sosial',
    'Peta Wilayah Desa',
    'Peta Lokasi Kantor',
    'Detail Desa',
    'Statistik Pengunjung',
    'APBDes',
    'Hak cipta situs',
  ];

  const chunks = [];
  const lowerText = text.toLowerCase();
  const markers = headingMarkers
    .map((marker) => ({ marker, index: lowerText.indexOf(marker.toLowerCase()) }))
    .filter((item) => item.index !== -1)
    .sort((a, b) => a.index - b.index);

  for (let index = 0; index < markers.length; index += 1) {
    const current = markers[index];
    const next = markers[index + 1];
    const end = next ? next.index : text.length;
    const chunk = normalizeSpaces(text.slice(current.index, end));
    if (chunk.length > 20) {
      chunks.push(chunk.slice(0, 1800));
    }
  }

  const sentenceChunks = text
    .split(/(?<=[.!?])\s+|\s{2,}/)
    .map((chunk) => normalizeSpaces(chunk))
    .filter((chunk) => chunk.length > 35 && chunk.length < 1200);

  return Array.from(new Set([...chunks, ...sentenceChunks]));
}

function retrieveRelevantChunks(text, message) {
  const tokens = tokenize(message);
  if (tokens.length === 0) {
    return [];
  }

  return splitIntoChunks(text)
    .map((chunk) => ({ chunk, score: scoreText(chunk, tokens) }))
    .filter((item) => item.score >= 1)
    .sort((a, b) => b.score - a.score || a.chunk.length - b.chunk.length)
    .slice(0, 5);
}

async function buildFocusedContext(text, rawHtml, message) {
  const sections = [structuredFactsText()];
  const sources = [{ title: 'Website Resmi Desa Dukuhtengah', url: BASE_URL }];
  const debug = [];
  let confidence = 'medium';
  let matchedSection = 'structured_facts';
  let sourceTitle = 'Website Resmi Desa Dukuhtengah';
  let sourceUrl = BASE_URL;

  const wantsPemerintahDesa = includesAny(message, [
    'kepala desa', 'perangkat', 'pemerintah desa', 'pemerintahan desa', 'sekretaris',
    'bendahara', 'kaur', 'kasi', 'kasi kesra', 'kasi pelayanan',
  ]);
  const wantsDetailDesa = includesAny(message, [
    'alamat', 'kantor', 'lokasi', 'telepon', 'email', 'kodepos', 'kode pos', 'jam layanan', 'jam buka',
  ]);
  const wantsAgenda = includesAny(message, ['agenda', 'kegiatan', 'acara']);
  const wantsArticle = includesAny(message, ['artikel', 'berita', 'ruwat', 'rekso', 'harmoni', 'budaya']);

  if (wantsDetailDesa) {
    const detail = extractDetailDesa(text);
    sections.push(detail.text);
    confidence = 'high';
    matchedSection = 'detail_desa';
    debug.push(detail.found ? 'detail_desa_from_website' : 'detail_desa_from_structured_facts');
  }

  if (wantsPemerintahDesa) {
    const pemerintah = extractPemerintahDesa(text);
    sections.push(pemerintah.text);
    confidence = 'high';
    matchedSection = matchedSection === 'structured_facts' ? 'pemerintah_desa' : `${matchedSection},pemerintah_desa`;
    debug.push(pemerintah.found ? 'pemerintah_desa_from_website' : 'pemerintah_desa_from_structured_facts');
  }

  if (wantsAgenda) {
    const agenda = extractAgenda(text);
    sections.push(agenda.text);
    confidence = agenda.found ? 'high' : 'medium';
    matchedSection = matchedSection === 'structured_facts' ? 'agenda' : `${matchedSection},agenda`;
    debug.push(agenda.found ? 'agenda_from_website' : 'agenda_empty_or_not_found');
  }

  const articleContext = await findArticleContext(rawHtml, message);
  if (wantsArticle || articleContext) {
    if (articleContext) {
      sections.push(articleContext.text);
      for (const article of articleContext.candidates) {
        sources.push({ title: article.title, url: article.url });
      }
      sourceTitle = articleContext.candidates[0].title;
      sourceUrl = articleContext.candidates[0].url;
      confidence = articleContext.usedDetail ? 'high' : (confidence === 'high' ? 'high' : 'medium');
      matchedSection = matchedSection === 'structured_facts' ? 'artikel_terkait' : `${matchedSection},artikel_terkait`;
      debug.push(articleContext.usedDetail ? 'article_detail_fetched' : 'article_link_matched_from_homepage');
    } else {
      debug.push('article_intent_no_matching_article');
    }
  }

  const retrieved = retrieveRelevantChunks(text, message);
  if (retrieved.length > 0) {
    sections.push(['POTONGAN WEBSITE TERKAIT', ...retrieved.map((item) => item.chunk)].join('\n\n'));
    debug.push(`keyword_retrieval_${retrieved.length}_chunks`);
    if (matchedSection === 'structured_facts') {
      matchedSection = 'keyword_retrieval';
    }
  }

  const content = sections.filter(Boolean).join('\n\n').slice(0, 9000).trim();
  if (!content) {
    return {
      content: FALLBACK_NOT_FOUND,
      sources,
      confidence: 'low',
      matchedSection: 'not_found',
      sourceTitle,
      sourceUrl,
      debug: ['no_context_found'],
    };
  }

  return {
    content,
    sources,
    confidence,
    matchedSection,
    sourceTitle,
    sourceUrl,
    debug,
  };
}

const cleanText = cleanHtml(htmlStr);
const focused = await buildFocusedContext(cleanText, htmlStr, normalizedMessage);

return [{
  json: {
    website_content: focused.content,
    full_website_excerpt: normalizeSpaces(cleanText).slice(0, 1200),
    message: userMessage,
    source_url: focused.sourceUrl,
    source_title: focused.sourceTitle,
    retrieval_reason: focused.debug.join('; ') || 'structured_facts_default',
    matched_section: focused.matchedSection,
    sources: focused.sources,
    confidence: focused.confidence,
    retrieval_debug: {
      reason: focused.debug,
      matched_section: focused.matchedSection,
      source_url: focused.sourceUrl,
      content_length: focused.content.length,
    },
  },
}];
